+/* 화면 맥락 도우미(spec 015). 층 순서: 버튼 54 < 말풍선 55 < 대화상자 60·61 < 물음표 도움말 80. */
+
+.fab {
+  position: fixed;
+  z-index: 54;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 56px;
+  height: 56px;
+  padding: 0;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: 999px;
+  background: var(--thorp-surface-raised, var(--thorp-background));
+  color: var(--thorp-accent, var(--thorp-foreground));
+  box-shadow: 0 10px 28px rgb(0 0 0 / 22%);
+  cursor: grab;
+  touch-action: none;
+  transition:
+    top 0.18s ease,
+    left 0.18s ease,
+    right 0.18s ease,
+    box-shadow 0.18s ease;
+}
+
+.fab:hover {
+  box-shadow: 0 12px 32px rgb(0 0 0 / 28%);
+}
+
+.fab:focus-visible {
+  outline: var(--thorp-focus-outline, 2px solid var(--thorp-accent));
+  outline-offset: var(--thorp-focus-offset, 2px);
+}
+
+.fab[data-dragging='true'] {
+  cursor: grabbing;
+  transition: none;
+}
+
+.fab[data-narrow='true'] {
+  right: 16px;
+  bottom: 16px;
+  cursor: pointer;
+  touch-action: auto;
+}
+
+.fab[aria-expanded='true'] {
+  background: var(--thorp-accent-soft, var(--thorp-surface-raised));
+  color: var(--thorp-action-foreground, var(--thorp-accent));
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .fab {
+    transition: none;
+  }
+}
+
+/* 넓은 화면의 말풍선. 비교 대상 팝오버와 같은 표면이고 한 층 아래다. */
+.popover {
+  z-index: 55;
+  display: flex;
+  flex-direction: column;
+  width: min(400px, calc(100vw - 32px));
+  max-height: min(600px, var(--radix-popover-content-available-height, calc(100svh - 32px)));
+  overflow: hidden;
+  border: 1px solid var(--thorp-line-strong);
