+  cursor: pointer;
+}
+
+.example:hover {
+  border-color: var(--thorp-line-control-hover, var(--thorp-line-strong));
+}
+
+.log {
+  display: flex;
+  flex-direction: column;
+  gap: 12px;
+  margin: 0;
+  padding: 0;
+  overflow-y: auto;
+  list-style: none;
+  min-height: 0;
+}
+
+.exchange {
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+}
+
+.question {
+  align-self: flex-end;
+  max-width: 90%;
+  margin: 0;
+  padding: 8px 12px;
+  border-radius: 14px 14px 4px 14px;
+  background: var(--thorp-accent-soft, var(--thorp-background));
+  color: var(--thorp-action-foreground, var(--thorp-foreground));
+  overflow-wrap: anywhere;
+}
+
+.pending,
+.answer {
+  margin: 0;
