+    animation: none;
+  }
+}
+
+.answer[data-status='INSUFFICIENT_EVIDENCE'],
+.answer[data-status='OUT_OF_SCOPE'] {
+  color: var(--thorp-copy);
+}
+
+.failure {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 8px;
+  color: var(--thorp-negative, var(--thorp-foreground));
+}
+
+.failure p {
+  margin: 0;
+  flex: 1 1 200px;
+}
+
+.form {
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+}
+
+.input {
+  width: 100%;
+  resize: vertical;
+  padding: 8px 10px;
+  border: 1px solid var(--thorp-line-control, var(--thorp-line));
+  border-radius: var(--thorp-radius-control, 8px);
+  background: var(--thorp-background);
+  color: var(--thorp-foreground);
+  font: inherit;
+}
+
+.formRow {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 8px;
+}
+
+.counter {
+  font-size: 0.8rem;
+  color: var(--thorp-muted);
+  font-variant-numeric: tabular-nums;
+}

